// ── divide o livro em capítulos (títulos "Capítulo N", "# ...", ou vários arquivos) ──
const RV_CAP = /^\s*(?:#{1,3}\s*)?(?:cap[ií]tulo|cap\.)\s*([0-9]{1,3}|[ivxlcdm]{1,7})\b\s*[-–—:.]?\s*(.*)$/i;
function rvDivide(texto, arquivos) {
  const limpa = t => String(t || '').replace(/\r\n?/g, '\n').replace(/[​﻿]/g, '');
  const linhasDe = t => limpa(t).split('\n').map(l => l.replace(/[ \t]+/g, ' ').trim()).filter(Boolean);
  let caps = [];
  if (Array.isArray(arquivos) && arquivos.length > 1) {
    caps = arquivos.map((a, i) => {
      const ls = linhasDe(a.texto); let titulo = rvL(a.nome, 80).replace(/\.(txt|md|docx|pdf)$/i, '');
      if (ls.length && (RV_CAP.test(ls[0]) || /^#{1,3}\s/.test(ls[0]))) { const m = ls[0].match(RV_CAP); titulo = rvL(m ? (m[2] || ls[0]) : ls[0].replace(/^#+\s*/, ''), 80) || titulo; ls.shift(); }
      return { titulo, linhas: ls };
    });
