    const ls = linhasDe(texto || (arquivos && arquivos[0] && arquivos[0].texto));
    const marca = ls.map(l => RV_CAP.test(l) && l.length < 120);
    const usaHash = marca.filter(Boolean).length < 2 && ls.filter(l => /^#{1,2}\s/.test(l)).length >= 2;
    let atual = null;
    ls.forEach((l, i) => {
      const ehTitulo = usaHash ? /^#{1,2}\s/.test(l) : marca[i];
      if (ehTitulo) { const m = l.match(RV_CAP); atual = { titulo: rvL(m ? (m[2] || l.replace(/^#+\s*/, '')) : l.replace(/^#+\s*/, ''), 80), linhas: [] }; caps.push(atual); }
      else { if (!atual) { atual = { titulo: 'Abertura', linhas: [] }; caps.push(atual); } atual.linhas.push(l); }
    });
