  return caps.filter(c => c.linhas.length).map((c, i) => ({ n: i + 1, titulo: c.titulo || `Capítulo ${i + 1}`, linhas: c.linhas, palavras: c.linhas.reduce((s, l) => s + rvPalavras(l), 0) }));
}
const rvNumera = linhas => linhas.map((l, i) => `L${i + 1}: ${l}`).join('\n');
