function rvRepeticoes(caps) {
  const total = caps.reduce((s, c) => s + c.palavras, 0), MIN = Math.max(3, Math.round(total / 10000));
  const nomes = rvNomesProprios(caps), g = {};
  caps.forEach(c => c.linhas.forEach(l => {
    const t = rvTokens(l).map(x => x.toLowerCase());
    for (let n = 2; n <= 5; n++) for (let i = 0; i + n <= t.length; i++) {
      const w = t.slice(i, i + n), conteudo = w.filter(x => !RV_PARADAS.has(x) && !nomes.has(x) && x.length > 2);
      if (!conteudo.length || RV_PARADAS.has(w[n - 1]) && n > 2) continue;
      const k = w.join(' '); g[k] = g[k] || { n, total: 0, por: {} }; g[k].total++; g[k].por[c.n] = (g[k].por[c.n] || 0) + 1;
    }
  }));
  let lista = Object.entries(g).filter(([, v]) => v.total >= MIN).map(([k, v]) => ({ expressao: k, ...v }));
  lista = lista.filter(a => !lista.some(b => b.n > a.n && b.total >= a.total * 0.8 && (' ' + b.expressao + ' ').includes(' ' + a.expressao + ' ')));
  return lista.sort((a, b) => b.total * Math.sqrt(b.n) - a.total * Math.sqrt(a.n)).slice(0, 25).map(x => {
    const pico = Object.entries(x.por).sort((a, b) => b[1] - a[1])[0];
