const RV_PARADAS = new Set('a o as os um uma uns umas de do da dos das em no na nos nas por para pra pro com sem que e ou mas se é ser foi era ao à às aos me te lhe eu ele ela eles elas você vocês nós meu minha meus minhas seu sua seus suas isso isto aquilo esse essa este esta não sim mais menos muito muita já só também quando como onde porque então tinha tem ter estava está tá lá aí ali aqui num numa pelo pela pelos pelas até depois antes ainda nem mesmo tudo nada todo toda foi vai vou ia tão bem mal sobre entre gente quem qual cada outro outra'.split(' '));
function rvTokens(l) { return (l.match(/[\p{L}\p{N}][\p{L}\p{N}'’-]*/gu) || []); }
function rvNomesProprios(caps) {
  const cont = {};
  caps.forEach(c => c.linhas.forEach(l => rvTokens(l).forEach((t, i) => { const k = t.toLowerCase(); cont[k] = cont[k] || [0, 0]; cont[k][0]++; if (i > 0 && /^\p{Lu}/u.test(t)) cont[k][1]++; })));
  return new Set(Object.entries(cont).filter(([, [n, m]]) => n >= 2 && m / n > 0.7).map(([k]) => k));
}
function rvRepeticoes(caps) {
  const total = caps.reduce((s, c) => s + c.palavras, 0), MIN = Math.max(3, Math.round(total / 10000));
  const nomes = rvNomesProprios(caps), g = {};
  caps.forEach(c => c.linhas.forEach(l => {
    const t = rvTokens(l).map(x => x.toLowerCase());
    for (let n = 2; n <= 5; n++) for (let i = 0; i + n <= t.length; i++) {
      const w = t.slice(i, i + n), conteudo = w.filter(x => !RV_PARADAS.has(x) && !nomes.has(x) && x.length > 2);
      if (!conteudo.length || RV_PARADAS.has(w[n - 1]) && n > 2) continue;
      const k = w.join(' '); g[k] = g[k] || { n, total: 0, por: {} }; g[k].total++; g[k].por[c.n] = (g[k].por[c.n] || 0) + 1;
