  });
}
const RV_MARCAS = [['como quem', /\bcomo quem\b/gi], ['como se', /\bcomo se\b/gi], ['de repente', /\bde repente\b/gi], ['advérbios em -mente', /\b\p{L}{4,}mente\b/giu],
  ['reticências', /\.\.\.|…/g], ['exclamações', /!/g], ['"você" fora de diálogo', null], ['itálico longo (+120 letras)', /\*[^*\n]{120,}\*|_[^_\n]{120,}_/g]];
