  const erros = []; let datas = 0;
  const re = new RegExp(`\\b(domingo|segunda|ter[çc]a|quarta|quinta|sexta|s[áa]bado)(?:-feira)?\\b[^.\\n]{0,25}?\\b(\\d{1,2})\\s+de\\s+(${RV_MESES.join('|').replace('ç', '[çc]')})`, 'gi');
  caps.forEach(c => c.linhas.forEach((l, i) => { let m; re.lastIndex = 0;
    while ((m = re.exec(l))) {
