      const real = RV_DIAS[new Date(Date.UTC(ano, mes, dia)).getUTCDay()], dito = rvSemAcento(m[1].toLowerCase());
      if (rvSemAcento(real) !== dito) erros.push({ onde: `Cap${rvCapN(c.n)}:${i + 1}`, escrito: m[0], certo: `${dia}/${mes + 1}/${ano} é ${real}${['domingo', 'sábado'].includes(real) ? '' : '-feira'}` });
    } }));
  return { conferido: true, erros, datas, ano };
}
function rvNomes(caps) {
  const chave = t => rvSemAcento(t).toLowerCase().replace(/h/g, '').replace(/(.)\1/g, '$1');
  const grupos = {};
  caps.forEach(c => c.linhas.forEach((l, i) => rvTokens(l).forEach((t, j) => {
