const RV_PRIOS = ['ALTA', 'MÉDIA', 'BAIXA'];
const rvPrio = p => { const s = rvSemAcento(String(p || '')).toUpperCase(); return s.startsWith('A') ? 'ALTA' : s.startsWith('B') ? 'BAIXA' : 'MÉDIA'; };
const rvAcoes = (v, agente) => rvLista(v, 30).filter(a => a && (a.o_que || a.acao)).map(a => ({ prioridade: rvPrio(a.prioridade), onde: rvL(a.onde, 40), o_que: rvL(a.o_que || a.acao, 300), agente }));
